'use client'

import { useRouter } from 'next/navigation'
import { type MouseEventHandler, type ReactNode } from 'react'

type NavButtonProps = {
  href?: string
  back?: boolean
  className?: string
  children: ReactNode
}

export function NavButton({ href, back, className, children }: NavButtonProps) {
  const router = useRouter()

  const onClick: MouseEventHandler = () => {
    if (back) {
      router.back()
    } else if (href) {
      router.push(href)
    }
  }

  return (
    <button type="button" className={className} onClick={onClick}>
      {children}
    </button>
  )
}

